// Uncontrolled
<SwitchTab
  items={[
    { id: "all",      label: "All"      },
    { id: "active",   label: "Active"   },
    { id: "archived", label: "Archived" },
  ]}
  defaultValue="all"
  size="m"
/>

// Controlled
const [view, setView] = useState("all")
<SwitchTab
  items={items}
  value={view}
  onChange={setView}
